var DUSK_NIGHT_MIN = 18 * 60 + 30; /* 18:30 起算晚上 */
function timeBucket() {
  var mins = gameMinutes();
  if (mins === null) return 'day';
  if (mins >= DUSK_NIGHT_MIN || mins < DAY_FROM_MIN) return 'night';
  if (mins >= DUSK_FROM_MIN) return 'dusk';
  return 'day';
}

