/* ★ v159：神社场景组按「季节 → 时段」取图。
   季节档没给某张（比如 春 的夜图，就是夏夜那张逐字节副本）时，
   自动回退到 base 组，和 pickTimeUrl 的降级规则叠着用，永不白屏。 */
function shrineSetUrl(set) {
  if (!set) return '';
  var se = '';
  try { se = thSeasonOf(); } catch (eS) {}
  var sub = (se && set.seasons) ? set.seasons[se] : null;
  if (sub) {
    var u = pickTimeUrl(sub);
    if (u) return u;
  }
  return pickTimeUrl(set);
}

