/* ★ v165c：时间落库是 年/月/日/精确时间("HH:MM") 四件套。
   统一走 thTimeRead()，拿不到时间时返回 null（夜间判定按「不夜间」处理）。 */
function gameMinutes() {
  try {
    if (typeof thTimeRead !== 'function') return null;
    var v = thTimeRead();
    if (!v) return null;
    var hm = thHMParse(v.精确时间);
    return (hm.h >= 0 ? hm.h : 0) * 60 + (hm.mi >= 0 ? hm.mi : 0);
  } catch (e) { return null; }
}
function isNightNow() {
  var mins = gameMinutes();
  if (mins === null) return false;
  return mins >= NIGHT_FROM_MIN || mins < NIGHT_TO_MIN;
}
function nightImgFor(sceneName) {
  if (!sceneName) return '';
  if (NIGHT_IMGS[sceneName]) return NIGHT_IMGS[sceneName];
  /* 路段：按「A通往B」里的 A 取；纯乡村小路那几条统一用乡村小路的夜图 */
  var cut = sceneName.indexOf('通往');
  if (cut > 0) {
    var from = sceneName.slice(0, cut).replace(/^乡村小路-/, '');
    if (NIGHT_IMGS[from]) return NIGHT_IMGS[from];
  }
  if (sceneName.indexOf('乡村小路') !== -1 && NIGHT_IMGS['乡村小路']) return NIGHT_IMGS['乡村小路'];
  return '';
}

function getSceneBgUrl(sceneName) {
  var name = String(sceneName || '').trim();
  if (!name) return '';
  /* ★ v135：四季 / 天气图池优先；没填的键自动回退到下面的原图逻辑 */
  var seasonUrl = seasonSceneUrl(name);
  if (seasonUrl) return seasonUrl;
  /* ★ v136：新插图版本专属场景图（按地点名 / 场景键命中）；没给链接就回退旧图 */
  var artScene = thArtSceneUrl(name);
  if (artScene) return artScene;

  /* ═══ 公寓篇：一切照图床走 ═══ */
  if (isApartmentScene(name)) {
    var canon = normalizeApartmentPlace(name) || name;
    /* ★ v165f：便利店真图接上了 —— 这里必须调函数，不能读变量。
       ──────────────────────────────────────────────────────────────
       走过的弯路（三版，全是坑，写下来防止有人又改回去）：
         v94~v165e 前半：`if (canon.indexOf('便利店') !== -1) return '';`
                        一句「图床里没有便利店」直接判死刑，下面 SCENE_IMGS 那张图
                        永远走不到。玩家原话「便利店和前的图好像掉了」—— 是根本没接上。
         v165e 后半：    改成返回 CONVENIENCE_FRONT_IMG / _INNER_IMG 两个变量，
                        但那时这俩变量的值是**内嵌 SVG 占位符**（一块白板子写 24H）。
                        能显示了，但显示的是占位符不是画。
         v165f（现在）： 玩家用 ComfyUI 出了整套「四季 × 三时段」真图，已推图床。
       ⚠ 所以这里是 return 一次**函数调用**，不是读变量：
         convenienceFrontUrl() 内部按 thSeasonOf() 选季节组、再按 timeBucket() 选时段，
         变量（CONVENIENCE_FRONT_IMG）只是玩家手动覆盖用的空槽位，默认是空串。
         读变量 = 永远返回空串 = 又变成「图掉了」。 */
    if (canon.indexOf('便利店') !== -1) {
      /* 店里 / 店外分两张；「便利店里 / 便利店里面 / 便利店内部」含「里」或「内」就走进店那张 */
      var inShop = (canon.indexOf('里') !== -1) || (canon.indexOf('内') !== -1);
      return inShop ? convenienceInnerUrl() : convenienceFrontUrl();
    }
    if (canon.indexOf('对面公园') !== -1) return pickTimeUrl(SCENE_IMG_SETS.park_apartment);
    if (canon.indexOf('号门') !== -1) return pickTimeUrl(SCENE_IMG_SETS.apartment_door);
    if (canon.indexOf('走廊') !== -1) return pickTimeUrl(SCENE_IMG_SETS.apartment_hall);
    if (canon.indexOf('公寓楼下') !== -1) return pickTimeUrl(SCENE_IMG_SETS.apartment_gate);
    if (canon.indexOf('301室') !== -1) {
      var room = canon.split('-').pop();
      if (room.indexOf('门口') !== -1) return pickTimeUrl(SCENE_IMG_SETS.entry);
      if (room.indexOf('客厅') !== -1) return pickTimeUrl(SCENE_IMG_SETS.living);
      if (room.indexOf('厨房') !== -1) return pickTimeUrl(SCENE_IMG_SETS.kitchen);
      if (room.indexOf('浴室') !== -1) return pickTimeUrl(SCENE_IMG_SETS.bath);
      if (room.indexOf('主卧') !== -1) return pickTimeUrl(SCENE_IMG_SETS.room_main);
      if (room.indexOf('次卧') !== -1) return pickTimeUrl(SCENE_IMG_SETS.room_2nd);
      if (room.indexOf('杂物') !== -1) return pickTimeUrl(SCENE_IMG_SETS.storage);
      if (room.indexOf('阳台') !== -1) return pickTimeUrl(SCENE_IMG_SETS.balcony);
      return pickTimeUrl(SCENE_IMG_SETS.entry);
    }
    return pickTimeUrl(SCENE_IMG_SETS.apartment_gate);
  }

  /* ═══ ★ v98：神社篇 —— 先读分时段图（白天 / 日落 / 夜晚）；
     还没填的话就回退到 SCENE_IMGS 那张单图；再没有就返回空（保持上一张背景，不白屏） ═══ */
  if (isShrineScene(name)) {
    var sh = normalizeShrinePlace(name) || name;
    var shKey = SHRINE_IMG_KEY[sh];
    if (shKey && SHRINE_IMG_SETS[shKey]) {
      var shUrl = shrineSetUrl(SHRINE_IMG_SETS[shKey]);
      if (shUrl) return shUrl;
    }
    return SCENE_IMGS[sh] || '';
  }

  /* ═══ 夏越村：屋内用**乡村自己的老图**（绝不拉公寓 301 的房间图）═══ */
  var p = parseLocation(name);
  if (p.room) {
    if (VILLAGE_ROOM_IMGS[p.room]) return VILLAGE_ROOM_IMGS[p.room];
    if (p.room === 'yard')    return SCENE_IMGS[name] || '';             /* 各家前院沿用原图 */
  }

  /* ═══ 夏越村：户外先看图床有没有 ═══ */
  if (name.indexOf('小卖铺前') !== -1) return pickTimeUrl(SCENE_IMG_SETS.shop_front);
  if (name.indexOf('小卖铺里') !== -1) return pickTimeUrl(SCENE_IMG_SETS.shop_in);   /* 暂无图 */
  /* ★ v154：分时段优先（park 组里有 night），单图兜底。
     原写法 SCENE_IMGS[name] 在前，SCENE_IMG_SETS.park.night 永远走不到，夜里也是白天图。 */
  if (name.indexOf('公园') !== -1) return pickTimeUrl(SCENE_IMG_SETS.park) || SCENE_IMGS[name] || '';

  /* ═══ 其余（乡村小路 / 林间 / 大坝 / 代木场 / 村口 / 开场白）沿用旧图，天黑走夜图 ═══ */
  if (timeBucket() === 'night') {
    var nightUrl = nightImgFor(name);
    if (nightUrl) return nightUrl;
  }
  if (SCENE_IMGS[name]) return SCENE_IMGS[name];
  if (name.indexOf('乡村小路') !== -1) return ROAD_IMG;
  var cut = name.indexOf('通往');
  if (cut > 0) {
    var from = name.slice(0, cut).replace(/^乡村小路-/, '');
    if (SCENE_IMGS[from]) return SCENE_IMGS[from];
  }
  return '';   /* 认不出就不贴图，保持原背景 */
}

