var HOST = (function () {
  try { if (window.top && window.top.document && window.top.document.body) return window.top; } catch (e) {}
  try { if (window.parent && window.parent.document && window.parent.document.body) return window.parent; } catch (e) {}
  return window;
})();

function getDoc() { return HOST.document || document; }
/* ══ ★ v155：跨 document 找元素 ══
   以前全卡统一用 getDoc()，但 getDoc() 只认 HOST.document 一个。
   HOST 优先取 window.top —— 壳要是长在另一个 document 里（外置全屏、
   楼层外置、或酒馆把聊天塞进 iframe），所有 getElementById 全部返回 null，
   而且**静默**返回：函数第一行 `if (!x) return;` 就退了，控制台一声不吭。
   小地图「点了没反应」就是这个。
   这里不再赌 document 是哪一份，而是**挨个找**，谁有就算谁的。 */
function thDocList() {
  var out = [], d;
  try { d = document; if (d) out.push(d); } catch (e1) {}
  try { d = window.top && window.top.document; if (d && out.indexOf(d) < 0) out.push(d); } catch (e2) {}
  try { d = window.parent && window.parent.document; if (d && out.indexOf(d) < 0) out.push(d); } catch (e3) {}
  try { d = HOST && HOST.document; if (d && out.indexOf(d) < 0) out.push(d); } catch (e4) {}
  return out;
}
/* 壳真正所在的那份 document（找不到就退回 document） */
function thDocWithShell() {
  var ds = thDocList(), i;
  for (i = 0; i < ds.length; i++) {
    try { if (ds[i].getElementById('th-gal-shell-root')) return ds[i]; } catch (e) {}
  }
  return document;
}
/* 按 id 跨 document 找元素 —— 地图模块一律走这个 */
function thEl(id) {
  var ds = thDocList(), i, el;
  for (i = 0; i < ds.length; i++) {
    try { el = ds[i].getElementById(id); if (el) return el; } catch (e) {}
  }
  return null;
}
function qa(sel, c) { return Array.from((c || getDoc()).querySelectorAll(sel)); }

