  try { if (thAtTitleScreen()) return BGM_LISTS['神社'] || []; } catch (eT0) {}
  var arc = currentPlaceArea();
  /* ★ v153：还没进过局（读不到任何地点）时默认走神社。
     注意：**只要读到了地点**，就一定按地点走，这里只影响「一片空白」那一下。 */
  if (!arc) arc = normArc(TH_ARC_HINT || '神社');
