/* ══════════════════════════════════════════════════════════════
   ★ v31 变量读写：背包 / 商店 / 零花钱 / 村里热议 / 时间
   路径按你给的来，另外顺手兼容 玩家信息 这个写法。
   ══════════════════════════════════════════════════════════════ */
function safeObj(v) { return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {}; }

function statePlayer() {
  var sd = getSD();
  return safeObj(sd.主角信息 || sd.玩家信息 || sd.玩家 || sd.基本信息);
}
function statePlayerAlias() {
  var sd = getSD();
  return safeObj(sd.玩家信息 || sd.主角信息);
}
function stateGlobal() {
  var sd = getSD();
  return safeObj(sd.全局);
}
function stateTime() {
  var sd = getSD();
  return safeObj(sd.时间);
}

/* ══════════════════════════════════════════════════════════════════════════
   ★ v164 / v165c：时间底座 —— 年份 / 月份 / 日期 / 精确时间 四件套

   用户原话：「第几天这个变量就去掉吧，不要了。」
   用户原话（否决拆字段）：「你他妈为什么要搞时，分，你不能合在一起搞成精确时间吗，多此一举」

   ── 为什么必须动这一层 ──
   旧结构是「季节 + 第几天 + 精确时间(HH:MM 字符串)」，月日是**算出来**的：
   季节决定一个锚点 DOY，第几天再加偏移。这套设计的每个下游都很难受：

     · 没法表示「年份」—— 玩家问「今年是哪年」，卡里没有答案。
     · 月日只能靠季节锚点反推，玩家手改「第几天」时月日会跟着乱跳。
     · 「月」和「日」不是独立事实，跨月只能靠 365 取模硬推。
     · AI 写时间经常写成 "8:00" / "8：00" / "08:00"，字符串解析天天打架。

   现在直接存四个值：年份、月份、日期、精确时间（"HH:MM" 五字符字符串）。
   季节不再单独存 —— 由月份推导（3-5 春 / 6-8 夏 / 9-11 秋 / 12-2 冬），
   一个事实只存一份，不会出现「七月配冬天」这种自相矛盾的状态。

   ── 为什么时刻只有一条 ──
   v164 一度拆成「时」「分」两个数字字段，是多余的两份真相：
   拆开之后每次推进都要同时算两个数、同时进位、同时写回，
   任何一处漏写就会出现「时 23 分 95」这种非法状态。
   时刻本来就是一个量，所以只存一条 "HH:MM" —— 解析/格式化各一个函数，
   内部要算的时候临时拆成 h/mi，落库永远只有这一条。

   ── 兼容 ──
   旧存档里还是 {第几天, 精确时间} 或 v164 过渡的 {时, 分}。
   thTimeRead() 读到它们会自动换算成新四件套（旧结构用季节锚点，
   和旧版 thCalDateOf 的算法完全一致），
   所以老存档打开后月日和以前一模一样，只是从此按新结构存。
   ══════════════════════════════════════════════════════════════════════════ */

/* 默认值：和落库结构完全一致的四个字段，没有任何仅供兜底的影子字段。
   解析失敗时一律回落到这里，所以这里写什么，卡就默认从什么时候开始。 */
/* ══ 时间兜底值 ══════════════════════════════════════════════════════
   ★ v165i：这段注释以前写「默认夏 / 7月26日」，现在依然如此，但**只是兜底**。
     真正开局的月日由 arcInitPatch 按玩家选的季节写（见 SEASON_START_DATE）——
     选冬就是 1 月 6 日，读不到的极老存档才落到这里的 7 月 26 日。 */
var TH_TIME_DEFAULT = { 年份: 2018, 月份: 7, 日期: 26, 精确时间: '07:40' };

/* 公历月天数；1/3/5/7/8/10/12 = 31，4/6/9/11 = 30，2 月看闰年 */
function thMonthDays(y, m) {
  var mm = parseInt(m, 10);
  if (mm === 2) return thIsLeapYear(y) ? 29 : 28;
  return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mm - 1] || 30;
}
function thIsLeapYear(y) {
  var yy = parseInt(y, 10);
  if (!(yy > 0)) return false;
  return (yy % 4 === 0 && yy % 100 !== 0) || (yy % 400 === 0);
}
/* 月份 → 季节。这是唯一的季节来源，别处不许再自己推。 */
function thSeasonByMonth(m) {
  var mm = parseInt(m, 10);
  if (mm >= 3 && mm <= 5) return '春';
  if (mm >= 6 && mm <= 8) return '夏';
  if (mm >= 9 && mm <= 11) return '秋';
  return '冬';
}
/* 星期几。用蔡勒公式（Zeller），对 1583 年之后的公历都成立。 */
function thWeekdayOf(y, m, d) {
  var yy = parseInt(y, 10), mm = parseInt(m, 10), dd = parseInt(d, 10);
  if (mm < 3) { mm += 12; yy -= 1; }
  var K = yy % 100, J = Math.floor(yy / 100);
  var h = (dd + Math.floor(13 * (mm + 1) / 5) + K + Math.floor(K / 4) + Math.floor(J / 4) + 5 * J) % 7;
  /* h: 0=周六 1=周日 2=周一 … 6=周五 */
  return ['六', '日', '一', '二', '三', '四', '五'][((h % 7) + 7) % 7];
}

/* 「第几天 → 月日」的旧算法，保留下来只做旧存档回填。
   新代码一律不要再调它。 */
function thLegacyDayToMD(day, season) {
  var sn = season || '夏';
  var anchor = TH_CAL_ANCHOR[sn] || TH_CAL_ANCHOR['夏'];
  var d = parseInt(day, 10);
  if (!(d >= 1)) d = 1;
  var doy = (((anchor - 1 + (d - 1)) % 365) + 365) % 365 + 1;
  var acc = 0, m = 1;
  /* ★ 这里不查 TH_CAL_MDAYS（那是旧卡自己的月长表，2 月固定 28），
     而是走公历的 thMonthDays —— 两者在 1..12 月长度上完全一致，
     只有闰年 2 月差一天，用公历更准。 */
  for (m = 1; m <= 12; m++) {
    var len = thMonthDays(2018, m);   /* 回填用平年，和旧算法逐位对齐 */
    if (doy <= acc + len) return { m: m, d: doy - acc };
    acc += len;
  }
  return { m: 12, d: 31 };
}

/* ── 读：永远返回四件套，永远合法 ──
   ★ v165c：用户原话「你他妈为什么要搞时，分，你不能合在一起搞成精确时间吗，多此一举」。
     v164 我把「精确时间」这个 HH:MM 字符串拆成了 时 / 分 两个数字字段，纯属自找麻烦：
     变量表多一行、JSONPatch 多一条 op、AI 每次要写两个字段、写歪一个就时间错。
     现在合回去：**年份 / 月份 / 日期 / 精确时间（"07:40"）**。
     内部算时间仍然用小时+分钟两个数，但那只是局部变量，不落库。
   ★ 兼容：老存档里如果是 时 / 分 两件套，读的时候自动拼成 "HH:MM"；
     年份 / 月份 / 日期 之外什么都没有的极老存档（季节+第几天），走旧换算。 */
function thTimeRead(src) {
  var t = src;
  if (!t || typeof t !== 'object') {
    try { t = stateTime(); } catch (e) { t = null; }
  }
  t = safeObj(t);

  /* 判定顺序很重要。
     · 有 年份/月份/日期 任一个 → 新结构（日期齐全的那种）
     · 没有日期、但有 第几天 → 极老存档，走旧换算
     · 日期和 第几天 都没有，只有 精确时间 / 时 / 分 → 当"只有时刻"，日期落默认
     ★ v165c 踩过的坑：不能把 精确时间 直接算进 hasNew ——
       旧存档是 { 第几天: 1, 精确时间: '07:40' }，那样会被误判成新结构，
       日期取不到就落成 1 月 1 日，一天都不对。 */
  var hasDate = (t.年份 !== undefined || t.月份 !== undefined || t.日期 !== undefined);
  var hasLegacyDay = (t.第几天 !== undefined);
  var hasSplit = (t.时 !== undefined || t.分 !== undefined);     /* v164 的过渡结构 */
  var hasAny = hasDate || hasLegacyDay || hasSplit || (t.精确时间 !== undefined);
  if (!hasAny) {
    return {
      年份: TH_TIME_DEFAULT.年份, 月份: TH_TIME_DEFAULT.月份, 日期: TH_TIME_DEFAULT.日期,
      精确时间: TH_TIME_DEFAULT.精确时间
    };
  }

  var y, mo, d, h, mi;

  if (hasDate) {
    /* 新结构 */
    y = parseInt(t.年份, 10);
    mo = parseInt(t.月份, 10);
    d = parseInt(t.日期, 10);
  } else if (hasLegacyDay) {
    /* 旧结构：季节 + 第几天 */
    var legacyDay = parseInt(t.第几天, 10);
    var season = '';
    try { season = (typeof thSeasonOf === 'function') ? thSeasonOf() : ''; } catch (eS) {}
    var md = thLegacyDayToMD(isNaN(legacyDay) ? 1 : legacyDay, season);
    y = 2018;
    mo = md.m;
    d = md.d;
  } else {
    /* 只有时刻，没有日期 → 日期落默认 */
    y = TH_TIME_DEFAULT.年份; mo = TH_TIME_DEFAULT.月份; d = TH_TIME_DEFAULT.日期;
  }

  /* 时刻：优先 精确时间；没有再拼 时/分（v164 过渡） */
  if (t.精确时间 !== undefined && t.精确时间 !== null && String(t.精确时间).trim()) {
    var mh = /^\s*(\d{1,2})\s*[:：]\s*(\d{1,2})/.exec(String(t.精确时间));
    h = mh ? parseInt(mh[1], 10) : NaN;
    mi = mh ? parseInt(mh[2], 10) : NaN;
  } else if (hasSplit) {
    h = parseInt(t.时, 10);
    mi = parseInt(t.分, 10);
  } else {
    h = NaN; mi = NaN;
  }

  if (!(y >= 1900)) y = TH_TIME_DEFAULT.年份;
  if (y > 2200) y = 2200;
  if (!(mo >= 1)) mo = TH_TIME_DEFAULT.月份;
  if (mo > 12) mo = 12;
  if (!(d >= 1)) d = 1;
  var maxD = thMonthDays(y, mo);
  if (d > maxD) d = maxD;
  /* 时刻兜底同样是「先解析 精确时间」，解析不出来才用默认那条 07:40 */
  var defHM = { h: 7, mi: 40 };
  (function (s) {
    var dm = /^\s*(\d{1,2})\s*[:：]\s*(\d{1,2})/.exec(String(s == null ? '' : s));
    if (dm) { defHM.h = parseInt(dm[1], 10); defHM.mi = parseInt(dm[2], 10); }
  })(TH_TIME_DEFAULT.精确时间);
  if (!(h >= 0)) h = defHM.h;
  if (h > 23) h = 23;
  if (!(mi >= 0)) mi = defHM.mi;
  if (mi > 59) mi = 59;

  /* 补零写成函数内部的小工具，thTimeRead 不依赖任何外部 helper
     （v165c 教训：一旦依赖外部函数，单测切片就抽不到，白报 ReferenceError） */
  var z2 = function (n) { n = parseInt(n, 10); if (!(n >= 0)) n = 0; return (n < 10 ? '0' : '') + n; };
  return { 年份: y, 月份: mo, 日期: d, 精确时间: z2(h) + ':' + z2(mi) };
}

/* 两位补零（时间格式化到处要用）。 */
function thPad2(n) { n = parseInt(n, 10); if (!(n >= 0)) n = 0; return (n < 10 ? '0' : '') + n; }

/* "07:40" → { h, mi }。解析失败给 NaN，交给调用方兜底。
   同样刻意做成自包含，不依赖别的函数。 */
function thHMParse(s) {
  var m = /^\s*(\d{1,2})\s*[:：]\s*(\d{1,2})/.exec(String(s == null ? '' : s));
  if (!m) return { h: NaN, mi: NaN };
  return { h: parseInt(m[1], 10), mi: parseInt(m[2], 10) };
}

/* ── 写：整块覆盖 /时间 ──
   写的是 年份 / 月份 / 日期 / 精确时间 四件套，顺手把 v164 留下的 时 / 分 清掉，
   免得一个存档里同时存在两种写法、读到一半新一半旧。
   注意：调用方拿到的是 patch.stat_data.时间 这个引用时，
   不要直接在原对象上改，走 thTimeApply()。 */
function thTimeWrite(t, patch) {
  var v = thTimeRead(t);
  function fill(target) {
    try { delete target.第几天; } catch (e) {}
    try { delete target.时; } catch (e) {}
    try { delete target.分; } catch (e) {}
    target.年份 = v.年份; target.月份 = v.月份; target.日期 = v.日期;
    target.精确时间 = v.精确时间;
  }
  var target = null;
  try {
    if (patch && patch.stat_data) {
      if (!patch.stat_data.时间 || typeof patch.stat_data.时间 !== 'object') patch.stat_data.时间 = {};
      target = patch.stat_data.时间;
    }
  } catch (eP) {}
  if (target) { fill(target); return target; }
  /* 没有 patch 就走三通道直接写 */
  try {
    var sd = getSD();
    if (sd) {
      if (!sd.时间 || typeof sd.时间 !== 'object') sd.时间 = {};
      fill(sd.时间);
    }
  } catch (e1) {}
  return v;
}

/* ── 推进：唯一允许改时间的地方 ──
   minutes 可以是负数（回拨）。内部把「精确时间」拆成小时+分钟当纯分钟数算，
   溢出就进位到日，日溢出就进位到月，月溢出就进位到年，年份变了就按新年判闰年。
   这样跨月、跨年、闰年 2 月 29 日全都不用特判。
   ★ 拆出来的小时/分钟只在函数内部用，落库的永远是 "HH:MM" 一条。 */
function thTimeAdvance(minutes, patch) {
  var add = Math.round(Number(minutes) || 0);
  var t = thTimeRead(patch ? (patch.stat_data || {}).时间 : null);
  var y = t.年份, mo = t.月份, d = t.日期;
  /* 自包含解析（单测会把本函数整段切出来跑，不能依赖模块级 thHMParse） */
  var hm = { h: NaN, mi: NaN };
  (function (s) {
    var mm = /^\s*(\d{1,2})\s*[:：]\s*(\d{1,2})/.exec(String(s == null ? '' : s));
    if (mm) { hm.h = parseInt(mm[1], 10); hm.mi = parseInt(mm[2], 10); }
  })(t.精确时间);
  var h = (hm.h >= 0) ? hm.h : 7;
  var mi = (hm.mi >= 0) ? hm.mi : 40;
  var totalMin = h * 60 + mi + add;

  /* 先把分钟数归到 [0, 1440) 之外的部分进日 */
  var dayCarry = Math.floor(totalMin / 1440);
  var rem = totalMin - dayCarry * 1440;
  if (rem < 0) { rem += 1440; dayCarry -= 1; }

  d += dayCarry;
  /* 往后进位 */
  while (d > thMonthDays(y, mo)) {
    d -= thMonthDays(y, mo);
    mo += 1;
    if (mo > 12) { mo = 1; y += 1; }
  }
  /* 往前退位 */
  while (d < 1) {
    mo -= 1;
    if (mo < 1) { mo = 12; y -= 1; }
    d += thMonthDays(y, mo);
  }
  if (y < 1900) { y = 1900; mo = 1; d = 1; }

  /* 补零同样自带（单测会整段切片跑，不能依赖模块级 thPad2） */
  var p2 = function (n) { n = parseInt(n, 10); if (!(n >= 0)) n = 0; return (n < 10 ? '0' : '') + n; };
  var out = {
    年份: y, 月份: mo, 日期: d,
    精确时间: p2(Math.floor(rem / 60)) + ':' + p2(rem % 60)
  };
  thTimeWrite(out, patch);
  return out;
}

/* ── 展示 ──
   style: 'full'   2018年7月26日 周四 07:40
          'date'   2018年7月26日
          'md'     7月26日
          'hm'     07:40
          'mdhm'   7月26日 07:40
          'ymd'    2018-07-26
          'w'      周四
   月日不补零（7月26日 而不是 07月26日），时刻补零（07:40）。
   这是中文的常规写法，也和玩家自己说话的方式一致。 */
function thTimeLabel(t, style) {
  var v = thTimeRead(t);
  var s = style || 'full';
  /* 自包含补零（单测会整段切片跑） */
  var p2 = function (n) { n = parseInt(n, 10); if (!(n >= 0)) n = 0; return (n < 10 ? '0' : '') + n; };
  /* v165c：精确时间就是现成的一条 "HH:MM"，不用再拼 时/分 */
  var hm = String(v.精确时间 || '00:00');
  var w = '周' + thWeekdayOf(v.年份, v.月份, v.日期);
  var md = v.月份 + '月' + v.日期 + '日';
  var ymd = v.年份 + '年' + md;
  if (s === 'hm') return hm;
  if (s === 'md') return md;
  if (s === 'mdhm') return md + ' ' + hm;
  if (s === 'date') return ymd;
  if (s === 'ymd') {
    return v.年份 + '-' + p2(v.月份) + '-' + p2(v.日期);
  }
  if (s === 'w') return w;
  return ymd + ' ' + w + ' ' + hm;
}

/* 与旧代码对接的薄封装：很多地方原来写 t.精确时间，换成这个即可 */
function thTimeHM(t) { return thTimeLabel(t, 'hm'); }
function thTimeDateKey(t) { return thTimeLabel(t, 'ymd'); }
function thTimeSeason(t) { return thSeasonByMonth(thTimeRead(t).月份); }

function getBag() { return safeObj(statePlayer().背包 || statePlayerAlias().背包); }
/* ★ v165e：背包的**显示**版本 —— 过滤掉已下架的专人道具。
   注意：只过滤显示，不去改写存档变量（改存档是另一个量级的动作，
   万一玩家将来想找回某件东西，原始数据还在）。买东西、用道具、看面板都走这个。 */
function getBagVisible() { return thFilterRemovedItems(getBag()); }
function getStock() { return safeObj(stateGlobal().商店); }

/* ★ v45：钱花光了就没处去 ， 每跨一天发一次零花钱。
   想做别的数额改 DAILY_ALLOWANCE 就行。 */
var DAILY_ALLOWANCE = 200;

function allowanceStorageKey() {
  /* ★ v118：同 energy / link，改用 currentChatId()（按【存档】分）。
     以前用 ctx.chatId（角色 id）：A 存档第 3 天领过零花钱，B 存档第 3 天就领不到。 */
  var id = 'default';
  try { id = currentChatId(); } catch (e) { id = 'default'; }
  return 'thGalAllowanceDay::' + id;
}

/* ★ v164：日期序数（1970-01-01 起的天数）。
   只用来算「隔了几天」，不做任何显示，所以不追求历法精度之外的严谨。 */
function thDaySerial(y, m, d) {
  y = Number(y) || 1970; m = Number(m) || 1; d = Number(d) || 1;
  /* 用 Date.UTC 保证闰年 / 月末边界正确 */
  try {
    return Math.floor(Date.UTC(y, m - 1, d) / 86400000);
  } catch (e) {
    return y * 372 + m * 31 + d;
  }
}

/* 日期变大就发一次；第一次进入只记下当天，不补发。
   ★ v164：key 从「第几天」数字改成「YYYY-MM-DD」，隔几天用日期序数算。 */
function checkDailyAllowance(sd) {
  try {
    var tv = null;
    try { tv = thTimeRead((sd || {}).时间); } catch (eT) { tv = null; }
    if (!tv) return;
    var todayKey = thTimeDateKey(tv);
    var todaySerial = thDaySerial(tv.年份, tv.月份, tv.日期);
    var key = allowanceStorageKey();
    var lastKey = null;
    try { lastKey = localStorage.getItem(key); } catch (e) {}
    if (lastKey === null || lastKey === '' || lastKey === 'undefined') {
      try { localStorage.setItem(key, todayKey); } catch (e) {}
      return;
    }
    if (lastKey === todayKey) return;
    /* 回填：老存档里存的是纯数字（第几天），直接覆盖，不补发 */
    if (/^\d+$/.test(String(lastKey))) {
      try { localStorage.setItem(key, todayKey); } catch (e) {}
      return;
    }
    try { localStorage.setItem(key, todayKey); } catch (e) {}
    var lastSerial = null;
    var lm = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(lastKey));
    if (lm) lastSerial = thDaySerial(lm[1], lm[2], lm[3]);
    var steps = 1;
    if (lastSerial !== null) steps = Math.min(Math.max(todaySerial - lastSerial, 1), 3);
    var gain = DAILY_ALLOWANCE * steps;
    setMoney(getMoney() + gain);
    /* ★ v131：日结出处按【当下所在片区】写，不再读篇章变量当开关。
       三处的人都在同一片世界里，只是这一夜人在哪儿就跟哪儿的口气说。 */
    var arcNow = '夏越村';
    try { arcNow = currentPlaceArea() || '夏越村'; } catch (eArc) {}
    /* ★ v164：文案里的「第 N 天」换成月日 */
    var dLabel = tv.月份 + '月' + tv.日期 + '日';
    /* ★ v98：日结的出处按篇章分（神社篇既没有久美子，也没有坐班工资） */
    showToast(arcNow === '神社'
      ? ('🌅 ' + dLabel + '，小铺的零钱结余又攒了一点，+ ' + gain)
      : (arcNow === '公寓'
        ? ('🌅 ' + dLabel + '，日结到账，钱包里多了 ' + gain + ' 零花钱')
        : ('🌅 ' + dLabel + '，久美子塞给你 ' + gain + ' 零花钱')));
  } catch (e) {}
}

function getMoney() {
  var a = statePlayer().零花钱;
  var b = statePlayerAlias().零花钱;
  var v = (a !== undefined && a !== null && a !== '') ? a : b;
  var n = parseInt(v, 10);
  return isNaN(n) ? 0 : n;
}

