/* 确定性伪随机：同一天 + 同一季节 → 同一天气，不会每轮刷新乱跳 */
function thRollWeather(day, season) {
  var se = thNormSeason(season);
  var odds = TH_WEATHER_ODDS[se] || TH_WEATHER_ODDS['夏'];
  var d = Number(day) || 1;
  var seed = d * 9301 + (TH_SEASONS.indexOf(se) + 1) * 49297 + 233;
  var r = ((Math.imul(seed, 1103515245) + 12345) >>> 0) % 10000 / 100;
  if (r < odds[0]) return '晴朗';
  if (r < odds[0] + odds[1]) return '阴天';
  return '下雨';
}
function thEnsureDailyWeather(day, force) {
  try {
    /* ★ v164：day 参数现在接受三种形态：
         ① 数字（年内第几天，旧调用点还在用）
         ② 'YYYY-MM-DD' 日期 key（新调用点传这个）
         ③ 不传 → 读当前时间
       种子统一换成「年内第几天」，保证「同一天同一季 → 同一天气」这条铁律不变。 */
    var doy, se;
    if (day === undefined || day === null || day === '') {
      var cal0 = thCalToday();
      doy = cal0.doy; se = thSeasonByMonth(cal0.m);
    } else if (typeof day === 'string' && day.indexOf('-') > 0) {
      var pm = /^(\d{4})-(\d{2})-(\d{2})/.exec(day);
      if (pm) {
        var calX = thCalDateOfFromMD(parseInt(pm[1], 10), parseInt(pm[2], 10), parseInt(pm[3], 10));
        doy = calX.doy; se = calX.season;
      } else {
        doy = 1; se = thSeasonOf();
      }
    } else {
      var d = Number(day);
      if (!isFinite(d) || d < 1) {
        var cal1 = thCalToday();
        d = cal1.doy;
      }
      doy = d;
      se = (typeof thSeasonOf === 'function') ? thSeasonOf() : '夏';
    }
    var stamp = doy + '|' + se;
    if (!force && window.__thWeatherStamp === stamp) return;
    window.__thWeatherStamp = stamp;
    thSetWeather(thRollWeather(doy, se));
  } catch (e) {}
}
/* 顶栏 HUD + 标题页背景：季节 / 天气一变就刷 */
