  try {
    var nowC = Date.now();
    var vpWc = dialogueViewportMetrics(bodyEl).vpW || 0;
    if (_galMetricsCache.v && (nowC - _galMetricsCache.at) < 400 && _galMetricsCache.vpW === vpWc) return _galMetricsCache.v;
  } catch (eC) {}
