  host.addEventListener('click', function (e) {
    var b = e.target && e.target.closest ? e.target.closest('.th-hud-mirror') : null;
    if (!b) return;
    e.preventDefault(); e.stopPropagation();
    var key = b.getAttribute('data-th-orig');
    var orig = findBtn(key);
    /* 原按钮在 display:none 的容器里，但 click() 不依赖可见性，照样能触发它的监听 */
    if (orig) { try { orig.click(); } catch (eX) {} }
    thHudArmAutoClose(shell);
    /* ★ v150：转发完把文字同步回来（音乐:开→关、高度:中→大 这类会变） */
    setTimeout(function () { thSyncHudMirror(shell); }, 60);
  });

  /* 常显开关 */
