  var btnSeasonSummer = shell.querySelector('#th-season-card-summer');
  var btnSeasonAutumn = shell.querySelector('#th-season-card-autumn');
  var btnSeasonWinter = shell.querySelector('#th-season-card-winter');
  var btnSeasonBack = shell.querySelector('#th-season-btn-back');
