    var b = thEl('th-pi-body') || piBody;
    var a = thEl('th-pi-age') || piAge;
    var m = thEl('th-pi-mind') || piMind;
    if (n) n.value = p['玩家姓名'];
    if (b) b.value = p['玩家外貌身材'];
    if (a) a.value = p['玩家年龄'];
    if (m) m.value = p['玩家性格'];
