      try {
        el.classList.remove('is-on');
        el.classList.remove('is-out');
        el.setAttribute('hidden', '');
        var bodyEl = el.querySelector('.th-gal-fest-body');
        if (bodyEl) bodyEl.innerHTML = '';
        var foot = el.querySelector('.th-gal-fest-foot');
        if (foot) { try { foot.innerHTML = '<span class="th-gal-fest-arrow">▶</span> 轻点继续'; } catch (eF2) {} }
      } catch (e) {}
      self.paras = null;
      self.meta = null;
      self.idx = 0;
